"use strict";

module.exports = function utilTypesProbe() {
  const types = require("node:util/types");
  return {
    ok:
      types.isDate(new Date()) &&
      types.isArrayBuffer(new ArrayBuffer(1)) &&
      types.isPromise(Promise.resolve()),
    summary: [
      "types:" + types.isDate(new Date()),
      types.isArrayBuffer(new ArrayBuffer(1)),
      types.isPromise(Promise.resolve()),
    ].join("/"),
  };
};
